75	#[derive(Clone)]
76	pub struct Item {
77	    item_type: ItemType,
78	    cursed: bool,
79	    enchantment: u32,
80	    material: String,
81	}
82	
83	impl Item {
84	    pub fn new(item_type: ItemType) -> Self {
85	        Self {
86	            item_type,
87	            cursed: false,
88	            enchantment: 0,
89	            material: String::new(),
90	        }
91	    }
92	
93	    /// The material the MHPCO recorded for this item.
94	    pub fn of_material(mut self, material: &str) -> Self {
95	        self.material = material.to_owned();
96	        self
97	    }
98	
99	    /// The item's enchantment level, as recorded by the MHPCO.
100	    pub fn with_enchantment(mut self, enchantment: u32) -> Self {
101	        self.enchantment = enchantment;
102	        self
103	    }
104	
105	    /// A cursed item carries the MHPCO's risk surcharge.
106	    pub fn cursed(mut self) -> Self {
107	        self.cursed = true;
108	        self
109	    }
110	
111	    /// The item-specific risk surcharges this item carries, charged against the
112	    /// item's own base premium rather than the policy total. A component carries
113	    /// none: the MHPCO records no curse, enchantment or material for one, so it
114	    /// is never an affected item.
115	    fn item_surcharge(&self) -> f64 {
116	        self.item_type
117	            .main_item_base_premium()
118	            .map_or(0.0, |item_base| item_base * self.risk_surcharge_rate())
119	    }
120	
121	    /// Highly enchanted for rating purposes. The MHPCO reads a separate, higher
122	    /// enchantment threshold when reimbursing damage, so this one is named for
123	    /// the premium it surcharges.
124	    fn is_highly_enchanted(&self) -> bool {
125	        self.enchantment >= HIGH_ENCHANTMENT_LEVEL
126	    }
127	
128	    /// The share of a damage amount the MHPCO reimburses for this item, under the
129	    /// reimbursement clauses it reads today. Only one clause reduces the share:
130	    /// damage to a very highly enchanted item is reimbursed at half. That
131	    /// enchantment threshold is a higher one than the threshold that surcharges
132	    /// the premium, and the MHPCO reads the two independently -- the level and the
133	    /// share, though, are the one clause, so they are read together here.
134	    ///
135	    /// The MHPCO's other reimbursement clause -- dragon material is reimbursed in
136	    /// full -- deliberately has no branch here. Full reimbursement is already what
137	    /// an item under no clause receives, and the half-reimbursement clause wins
138	    /// wherever both apply, so the dragon clause cannot move any share the MHPCO
139	    /// recognises. The material stays a recorded property of the item; give it a
140	    /// branch only when a clause makes it change a share.
141	    fn reimbursement_share(&self) -> f64 {
142	        if self.enchantment >= HALF_REIMBURSEMENT_LEVEL {
143	            HALF_REIMBURSEMENT
144	        } else {
145	            FULL_REIMBURSEMENT
146	        }
147	    }
148	
149	    /// Curse and high enchantment are independent risks; an item carrying both
150	    /// is surcharged for both.
151	    fn risk_surcharge_rate(&self) -> f64 {
152	        let curse = if self.cursed { CURSE_SURCHARGE } else { 0.0 };
153	        let enchantment = if self.is_highly_enchanted() {
154	            HIGH_ENCHANTMENT_SURCHARGE
155	        } else {
156	            0.0
157	        };
158	        curse + enchantment
159	    }
160	}
161	
162	const PROCESSING_FEE: u64 = 5;
163	const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
164	/// Cursed items add a risk surcharge on their own base premium.
165	const CURSE_SURCHARGE: f64 = 0.50;
166	/// Long-standing customers -- 2 or more years of business with the MHPCO --
167	/// receive a loyalty discount on the policy base premium.
168	const LOYALTY_YEARS: u32 = 2;
169	const LOYALTY_DISCOUNT: f64 = 0.20;
170	/// Customers receive a discount on each contract after their first.
171	const FOLLOW_UP_CONTRACT_DISCOUNT: f64 = 0.15;
172	/// Highly enchanted items -- enchantment level 5 or above -- add a risk
173	/// surcharge on their own base premium.
174	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
175	const HIGH_ENCHANTMENT_SURCHARGE: f64 = 0.30;
176	/// Components -- for example runes and moonstones -- share one price-list row.
177	const COMPONENT_BASE_PREMIUM: f64 = 25.0;
178	
179	/// How the MHPCO settles a rated premium into the amount it bills: the rated
180	/// fraction is rounded in the MHPCO's own favour -- upwards, the larger amount
181	/// -- and the processing fee is added to every premium at the very end.
182	fn settled_premium(rated: f64) -> u64 {
183	    rated.ceil() as u64 + PROCESSING_FEE
184	}
185	
186	/// The policy-wide modifier rate, charged against the policy base premium --
187	/// the sum of all item base premiums. The MHPCO nets its policy-wide modifiers
188	/// against one another: a first insurance carries an initial assessment
189	/// surcharge, a long-standing customer earns a loyalty discount, and every
190	/// contract after the customer's first earns a follow-up discount.
191	fn policy_modifier_rate(customer: &Customer, contract: Contract) -> f64 {
192	    let loyalty = if customer.is_long_standing() {
193	        LOYALTY_DISCOUNT
194	    } else {
195	        0.0
196	    };
197	    let follow_up = match contract {
198	        Contract::First => 0.0,
199	        Contract::FollowUp => FOLLOW_UP_CONTRACT_DISCOUNT,
200	    };
201	    FIRST_INSURANCE_SURCHARGE - loyalty - follow_up
202	}
203	
204	/// A building block of exactly 3 alike components is offered at this price
205	/// instead of the per-component base premium.
206	const COMPONENT_BLOCK_SIZE: usize = 3;
207	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
208	
209	fn component_charge(alike_count: usize) -> f64 {
210	    if alike_count == COMPONENT_BLOCK_SIZE {
211	        COMPONENT_BLOCK_BASE_PREMIUM
212	    } else {
213	        alike_count as f64 * COMPONENT_BASE_PREMIUM
214	    }
215	}
216	
217	/// The policy's components gathered into groups of alike ones, each group
218	/// reported as its size. Alike components are the ones charged together, so the
219	/// MHPCO's reading of "alike" -- same item type -- lives here and nowhere else.
220	fn alike_component_groups(items: &[Item]) -> Vec<usize> {
221	    let mut groups: Vec<(ItemType, usize)> = Vec::new();
222	    for component in items.iter().filter(|item| item.item_type.is_component()) {
223	        match groups
224	            .iter_mut()
225	            .find(|(group_type, _)| *group_type == component.item_type)
226	        {
227	            Some((_, count)) => *count += 1,
228	            None => groups.push((component.item_type, 1)),
229	        }
230	    }
231	    groups.into_iter().map(|(_, count)| count).collect()
232	}
233	
234	/// Main items are charged one price-list row each, individually.
235	fn main_items_base_premium(items: &[Item]) -> f64 {
236	    items
237	        .iter()
238	        .filter_map(|item| item.item_type.main_item_base_premium())
239	        .sum()
240	}
241	
242	/// Components are charged per group of alike components, so that a group of
243	/// exactly 3 earns the block price.
244	fn component_blocks_base_premium(items: &[Item]) -> f64 {
245	    alike_component_groups(items)
246	        .into_iter()
247	        .map(component_charge)
248	        .sum()
249	}
250	
251	/// The policy base premium is the sum of the items' base premiums, with alike
252	/// components charged as blocks.
253	pub fn policy_base_premium(items: &[Item]) -> f64 {
254	    main_items_base_premium(items) + component_blocks_base_premium(items)
255	}
256	
257	/// Item-specific modifiers apply to the base premium of the affected item, not
258	/// to the policy total.
259	fn item_surcharges(items: &[Item]) -> f64 {
260	    items.iter().map(Item::item_surcharge).sum()
261	}
262	
263	/// A customer's first contract with the MHPCO, or any contract after it.
264	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
265	pub enum Contract {
266	    First,
267	    FollowUp,
268	}
269	
270	/// What the MHPCO rates this policy at, as an exact fraction: the policy base
271	/// premium, modified policy-wide for the customer and the contract, plus the
272	/// surcharges carried by the individual affected items. This is the rating
273	/// decision; it is deliberately unrounded and carries no processing fee.
274	fn rated_premium(customer: &Customer, items: &[Item], contract: Contract) -> f64 {
275	    let policy_base = policy_base_premium(items);
276	    policy_base + policy_base * policy_modifier_rate(customer, contract) + item_surcharges(items)
277	}
278	
279	/// The premium the customer is billed: the MHPCO rates the policy, then settles
280	/// the rated amount into the amount billed.
281	pub fn quote(customer: &Customer, items: &[Item], contract: Contract) -> u64 {
282	    settled_premium(rated_premium(customer, items, contract))
283	}
284	
285	/// Damage to an item enchanted at this level or above is reimbursed at half.
286	const HALF_REIMBURSEMENT_LEVEL: u32 = 8;
287	const HALF_REIMBURSEMENT: f64 = 0.50;
288	const FULL_REIMBURSEMENT: f64 = 1.0;
289	
290	/// Components are insured at this value each.
291	const COMPONENT_INSURANCE_VALUE: u64 = 250;
292	
293	/// The total payout per policy is capped at this multiple of its insurance sum.
294	const CAP_MULTIPLE: u64 = 2;
295	
296	/// A deductible applies per damage event, once for each damaged item.
297	const DEDUCTIBLE_PER_DAMAGE: f64 = 100.0;
298	
299	/// A single damaged item reported in an incident.
300	pub struct Damage {
301	    item_type: ItemType,
302	    amount: i64,
303	}
304	
305	impl Damage {
306	    pub fn new(item_type: ItemType, amount: i64) -> Self {
307	        Self { item_type, amount }
308	    }
309	
310	    /// What the MHPCO reimburses for this one damaged item, as an exact
311	    /// fraction: the share of the damage amount the insured item's clauses
312	    /// allow, less the deductible that applies once per damage event.
313	    fn reimbursement(&self, insured: &Item) -> f64 {
314	        self.amount as f64 * insured.reimbursement_share() - DEDUCTIBLE_PER_DAMAGE
315	    }
316	}
317	
318	/// How the MHPCO settles a reimbursed amount into the amount it pays out: the
319	/// reimbursed fraction is rounded in the MHPCO's own favour -- downwards, the
320	/// smaller amount -- which is the opposite direction from a premium.
321	fn settled_payout(reimbursed: f64) -> u64 {
322	    reimbursed.floor() as u64
323	}
324	
325	/// What the MHPCO pays out on one claim.
326	#[derive(Debug, PartialEq, Eq)]
327	pub struct Settlement {
328	    pub payout: u64,
329	    pub remaining_cap: u64,
330	}
331	
332	/// A policy the MHPCO has written over a customer's items.
333	pub struct Policy {
334	    items: Vec<Item>,
335	    remaining_cap: u64,
336	}
337	
338	/// The MHPCO's record of which insured items have already answered for a damage
339	/// within one incident. The office holds each insured item to at most one damage
340	/// per incident, so an incident reporting more damaged items of a type than the
341	/// policy insures finds no further item to answer and is rejected whole.
342	///
343	/// The ledger is the MHPCO's coverage decision, kept apart from how a damage is
344	/// reimbursed once covered: which insured item answers may come to depend on the
345	/// item's own properties, while what it reimburses is already the clauses on
346	/// `Item` and `Damage`.
347	struct CoverageLedger {
348	    answered: Vec<usize>,
349	}
350	
351	impl CoverageLedger {
352	    /// A fresh ledger: no insured item has answered yet in this incident.
353	    fn for_incident() -> Self {
354	        Self {
355	            answered: Vec::new(),
356	        }
357	    }
358	
359	    /// The insured item that answers for this damage, recorded as answered so it
360	    /// cannot answer again in this incident. Any insured item of the reported type
361	    /// that has not yet answered will do: two items of a type carry the same
362	    /// reimbursement clauses, so which one is chosen cannot move the payout.
363	    fn assign(&mut self, policy: &Policy, damage: &Damage) -> Result<usize, String> {
364	        let index = policy
365	            .items
366	            .iter()
367	            .enumerate()
368	            .position(|(index, item)| {
369	                item.item_type == damage.item_type && !self.answered.contains(&index)
370	            })
371	            .ok_or_else(|| {
372	                format!(
373	                    "the policy does not cover a further item of type '{:?}'",
374	                    damage.item_type
375	                )
376	            })?;
377	        self.answered.push(index);
378	        Ok(index)
379	    }
380	}
381	
382	impl Policy {
383	    pub fn new(items: &[Item]) -> Self {
384	        Self {
385	            remaining_cap: Self::payout_cap(items),
386	            items: items.to_vec(),
387	        }
388	    }
389	
390	    /// The policy's insurance sum: the sum of the insured items' insurance
391	    /// values. Every insured item counts its own value, so two items of one type
392	    /// count twice, and a block of alike components counts each component -- the
393	    /// block discount is a premium offer and leaves the insurance sum untouched.
394	    fn insurance_sum(items: &[Item]) -> u64 {
395	        items
396	            .iter()
397	            .map(|item| item.item_type.insurance_value())
398	            .sum()
399	    }
400	
401	    /// What the MHPCO will pay out over the whole life of this policy. The cap is
402	    /// read off the insurance sum alone: premium modifiers rate the contract and
403	    /// do not raise the cap.
404	    fn payout_cap(items: &[Item]) -> u64 {
405	        CAP_MULTIPLE * Self::insurance_sum(items)
406	    }
407	
408	    /// The insured items that answer for the damages of one incident, in the
409	    /// order the damages were reported. Assigning coverage for the whole
410	    /// incident at once is what lets the MHPCO hold each insured item to at most
411	    /// one damage, and so notice an incident that over-reports a type.
412	    fn covering_items(&self, damages: &[Damage]) -> Result<Vec<&Item>, String> {
413	        let mut ledger = CoverageLedger::for_incident();
414	        damages
415	            .iter()
416	            .map(|damage| ledger.assign(self, damage).map(|index| &self.items[index]))
417	            .collect()
418	    }
419	
420	    /// What the MHPCO reimburses for a whole incident, as an exact fraction: each
421	    /// damaged item reimbursed under the clauses of the insured item that answers
422	    /// for it. This is the incident-level amount the MHPCO recognises, before it
423	    /// is settled into the amount paid out.
424	    fn reimbursed_total(&self, damages: &[Damage]) -> Result<f64, String> {
425	        let covering = self.covering_items(damages)?;
426	        Ok(damages
427	            .iter()
428	            .zip(covering)
429	            .map(|(damage, insured)| damage.reimbursement(insured))
430	            .sum())
431	    }
432	
433	    /// The MHPCO's cap clause, applied to one settled amount: the cap limits what
434	    /// the policy pays out over its whole life, so an amount the MHPCO would
435	    /// otherwise pay is reduced to whatever cap is left, and what it does pay
436	    /// draws the cap down. The clause reads the already-settled whole-G amount --
437	    /// the cap is stated in whole G and limits the payout, not the reimbursement
438	    /// behind it.
439	    fn pay_within_cap(&mut self, settled: u64) -> u64 {
440	        let payout = settled.min(self.remaining_cap);
441	        self.remaining_cap -= payout;
442	        payout
443	    }
444	
445	    /// The MHPCO settles an incident against this policy: it reimburses the
446	    /// incident under the policy's clauses, settles that total into whole G, and
447	    /// pays it out so far as the policy's cap still allows.
448	    pub fn claim(&mut self, damages: &[Damage]) -> Result<Settlement, String> {
449	        let reimbursed = self.reimbursed_total(damages)?;
450	        let payout = self.pay_within_cap(settled_payout(reimbursed));
451	        Ok(Settlement {
452	            payout,
453	            remaining_cap: self.remaining_cap,
454	        })
455	    }
456	}
